function renderTeacherTiles(){$('teacherTiles').innerHTML=dashboard.detalle.map(t=>'<div class="card" data-teachertile="'+t.id+'" style="cursor:pointer"><h3>'+avatar(t.gender)+' '+escape(t.docente)+'</h3><p class="muted">'+escape(t.categoria)+'</p><div class="minirow"><span>Dictado</span><strong>'+num(t.horas_lectivas)+' h</strong></div><div class="minirow"><span>Otras actividades</span><strong>'+num(t.otras_horas)+' h</strong></div><div class="minirow"><span>Meta lectiva</span><strong>'+num(t.requeridas)+' h</strong></div><div class="progress"><span style="width:'+Math.min(100,t.cobertura)+'%"></span></div>'+status(t)+'</div>').join('')||'<p>No hay docentes registrados.</p>';document.querySelectorAll('[data-teachertile]').forEach(e=>e.onclick=()=>{selectedTeacher=+e.dataset.teachertile;view('home');renderProfile(selectedTeacher)})}
function renderSelects(){let opts='<option value="">Seleccione docente</option>'+dashboard.detalle.map(t=>'<option value="'+t.id+'">'+escape(t.docente)+' · '+escape(t.categoria)+'</option>').join('');for(let id of ['courseTeacher','activityTeacher','planningTeacher','vacationTeacher']){let old=$(id).value;$(id).innerHTML=opts;$(id).value=old}let cat='<option value="">Seleccione categoría</option>'+categories.map(c=>'<option value="'+c.id+'">'+escape(c.name)+'</option>').join('');for(let id of ['teacherCategory','ruleCategory'])$(id).innerHTML=cat;let doc='<option value="">Seleccione PDF</option>'+sources.map(p=>'<option value="'+p.id+'">'+escape(p.filename)+'</option>').join('');$('rulePdf').innerHTML=doc;$('catSaved').innerHTML=categories.map(c=>'<div class="minirow"><span>'+escape(c.name)+'</span><strong>'+num(c.total_hours)+' h/sem</strong></div>').join('')}
function renderReport(){$('reportTable').innerHTML='<table><thead><tr><th>Docente</th><th>Categoría</th><th>Meta</th><th>Lectivas</th><th>Complementarias</th><th>Pendientes</th></tr></thead><tbody>'+dashboard.detalle.map(t=>'<tr><td>'+escape(t.docente)+'</td><td>'+escape(t.categoria)+'</td><td>'+num(t.requeridas)+'</td><td>'+num(t.horas_lectivas)+'</td><td>'+num(t.otras_horas)+'</td><td>'+num(t.pendientes)+'</td></tr>').join('')+'</tbody></table>'}
async function loadPlanning(){let id=+$('planningTeacher').value||selectedTeacher;if(!id){$('planningDetail').innerHTML='<p class="muted">Seleccione docente.</p>';return}$('planningTeacher').value=id;try{let d=await api('/api/teachers/'+id);$('planningDetail').innerHTML='<h3>'+escape(d.docente.docente)+'</h3><div class="config-grid"><div><h3>Cursos asignados</h3>'+d.cursos.map(c=>'<div class="minirow"><span>'+escape(c.name)+' · '+num(c.weekly_hours)+' h</span><button class="btn mini danger" data-delcourse="'+c.id+'">Eliminar</button></div>').join('')+'</div><div><h3>Actividades complementarias</h3>'+d.actividades.map(a=>'<div class="minirow"><span>'+escape(a.activity)+' · '+num(a.hours)+' h · '+escape(a.detail)+'</span><button class="btn mini danger" data-delactivity="'+a.id+'">Eliminar</button></div>').join('')+'</div></div><h3>Vacaciones registradas</h3>'+d.vacaciones.map(v=>'<div class="minirow"><span>'+escape(v.start_date)+' → '+escape(v.end_date)+' · '+escape(v.description)+'</span><button class="btn mini danger" data-delvac="'+v.id+'">Eliminar</button></div>').join('');document.querySelectorAll('[data-delvac]').forEach(b=>b.onclick=async()=>{if(await requestApproval('Eliminar vacaciones','¿Desea eliminar este período de vacaciones?')){await api('/api/vacations/'+b.dataset.delvac,{method:'DELETE'});await refresh();loadPlanning()}});document.querySelectorAll('[data-delcourse]').forEach(b=>b.onclick=async()=>{if(await requestApproval('Eliminar curso','¿Desea eliminar este curso asignado?')){await api('/api/courses/'+b.dataset.delcourse,{method:'DELETE'});await refresh();loadPlanning()}});document.querySelectorAll('[data-delactivity]').forEach(b=>b.onclick=async()=>{if(await requestApproval('Eliminar actividad','¿Desea eliminar esta actividad complementaria?')){await api('/api/assignments/'+b.dataset.delactivity,{method:'DELETE'});await refresh();loadPlanning()}})}catch(e){alertError(e)}}
$('categoryDropdown').onchange=e=>{selectedCategory=e.target.value;renderCategoryList();renderTeacherTable()};$('search').oninput=renderTeacherTable;$('importShortcut').onclick=()=>view('config');
function updateOfflineCacheStatus(){const el=$('offlineCacheStatus');if(!el||!window.InstOffline)return;const u=$('loginUser').value.trim();if(!u){el.dataset.ready='false';el.textContent='v53 · Escriba su usuario para comprobar si existe una copia cifrada en este navegador.';return}const ready=window.InstOffline.offlineReady(u);el.dataset.ready=String(ready);el.textContent='v53 · '+window.InstOffline.offlineStatus(u)+(ready?' Puede ingresar en modo solo lectura cuando Windows esté apagado.':' Encienda Windows e ingrese online una vez para preparar la copia.')}
$('loginUser').addEventListener('input',updateOfflineCacheStatus);
$('loginForm').onsubmit=async e=>{e.preventDefault();$('loginError').textContent='';try{const u=$('loginUser').value.trim(),p=$('loginPass').value;if(!u||!p)throw Error('Ingrese usuario y contraseña');const result=await window.InstOffline.login(u,p);token=result.token;window.INST_OFFLINE=result.offline;accountRole=result.offline?'viewer':result.role;$('adminName').textContent=u;sessionStorage.removeItem('inst_token');$('loginPass').value='';showApp();updateOfflineCacheStatus();if(!result.offline&&!result.cacheReady){$('loginHealth').textContent='● Online · Copia offline NO preparada';$('sideStatus').textContent='● Copia offline pendiente';alert('Ingreso online correcto, pero NO se verificó la copia cifrada offline. '+(result.cacheError||'Revise almacenamiento del navegador.'))}if(result.offline){$('loginHealth').textContent='● Copia cifrada · Solo lectura';$('sideStatus').textContent='● Copia offline · Solo lectura'}else{$('loginHealth').textContent='● Conectado · Sincronizando';}}catch(err){$('loginError').textContent=err.message;updateOfflineCacheStatus()}};
