async function v33ReportFilters(){
 try{
  const d=await api('/api/careers/analytics');
  const entries=Array.isArray(d)?d:(d.carreras||d.groups||d.grupos||d.detalle||[]);
  const faculty=$('reportFaculty'),career=$('reportCareer');
  const previousFaculty=faculty.value,previousCareer=career.value;
  const faculties=[...new Set(entries.map(x=>x.facultad||x.faculty).filter(Boolean))].sort();
  faculty.innerHTML='<option value="">Todas las facultades</option>'+faculties.map(x=>'<option value="'+escape(x)+'">'+escape(x)+'</option>').join('');
  if(faculties.includes(previousFaculty))faculty.value=previousFaculty;
  function updateCareers(){const prior=career.value||previousCareer;const names=[...new Set(entries.filter(x=>!faculty.value||(x.facultad||x.faculty)===faculty.value).map(x=>x.carrera||x.career).filter(Boolean))].sort();career.innerHTML='<option value="">Todas las carreras</option>'+names.map(x=>'<option value="'+escape(x)+'">'+escape(x)+'</option>').join('');if(names.includes(prior))career.value=prior;}
  faculty.onchange=()=>{updateCareers();v33Preview()};career.onchange=v33Preview;
  $('reportPeriod').oninput=v33Preview;$('reportDeadline').oninput=v33Preview;$('reportDean').oninput=v33Preview;
  updateCareers();await v33Preview();
 }catch(e){$('reportPreview').textContent='No fue posible cargar filtros: '+e.message}
}
