function requestApproval(title,description,phrase=''){
 return new Promise(resolve=>{
  const m=$('actionModal'),accept=$('modalAccept'),reject=$('modalReject'),field=$('modalPhrase'),wrap=$('modalPhraseWrap');
  $('modalTitle').textContent=title;$('modalDescription').textContent=description;
  field.value='';wrap.hidden=!phrase;field.placeholder=phrase;accept.disabled=!!phrase;if(phrase){const lbl=$('modalPhraseLabel');if(lbl)lbl.textContent='Escriba exactamente: '+phrase;}
  m.hidden=false;let settled=false;
  function close(ok){if(settled)return;settled=true;m.hidden=true;accept.onclick=null;reject.onclick=null;field.oninput=null;m.onclick=null;document.removeEventListener('keydown',onKey);resolve(ok)}
  function onKey(e){if(e.key==='Escape')close(false)}
  accept.onclick=()=>close(true);reject.onclick=()=>close(false);
  field.oninput=()=>{accept.disabled=field.value.trim()!==phrase};
  m.onclick=e=>{if(e.target===m)close(false)};
  document.addEventListener('keydown',onKey);
  if(phrase)field.focus();else reject.focus();
 });
}
